              pair: `${fgToken} on ${bgToken}`,
              reason: `not six-digit hex: ${unreadable.map((t) => `${t}=${theme.unresolved[t]}`).join(', ')}`,
            });
          }
          continue;
        }
        const value = ratio(fg, bg);
